def load_TIMIT_db(db_path='./', part='all'):
    '''
    path to Timit dataset
    part='all', 'train', 'test'
    '''
    #print("Creating TIMIT annotations list")
    if (part=='val'): part = 'train'

    speaker_info_file = os.path.join(db_path, "DOC/SPKRINFO.TXT")

    if (not os.path.exists(speaker_info_file) ): raise Exception("Make sure that the path to dataset and it's format is correct.")
    all_dataset_objects = []
    train_count = 0
    test_count = 0
    with open(speaker_info_file) as file:
        content = file.readlines()
        
        for line in content:
            if (line[0]!=';'):
                splits = line.split('  ')
                
                
                speaker_dialect = "DR" + splits[2]
                speaker_id = splits[1] + splits[0]
                is_train_set = True if (splits[3]=="TRN") else False
                is_test_set = True if (splits[3]=="TST") else False

                if (is_train_set):
                    speaker_dir = os.path.join(db_path, "TRAIN/"+speaker_dialect+"/"+speaker_id+"/")
                elif (is_test_set):
                    speaker_dir = os.path.join(db_path, "TEST/"+speaker_dialect+"/"+speaker_id+"/")
                else: raise Exception("Invalid set type", line)
                
                if ((part=='all') or ((part=='train') and is_train_set) or ((part=='test') and is_test_set)):
                    # Sorted: the list's order decides which clips a `subset` run draws, and
                    # directory order changes when the corpus is copied to another disk.
                    wav_files_paths = sorted(glob.glob(speaker_dir+'*.WAV'))
                    for s in range(0, len(wav_files_paths)):
                        wav_file_path = wav_files_paths[s]
                        sentence_id = os.path.basename(wav_file_path[:-4])
                        if (not os.path.exists(wav_file_path[:-4] + '.PHN')) or (not os.path.exists(wav_file_path[:-4] + '.TXT')) or (not os.path.exists(wav_file_path[:-4] + '.WRD')):
                            print(wav_file_path)
                            raise Exception("Transcription files a missing for a wav file.")
                        assert(os.path.exists(wav_file_path[:-4] + '.WAV'))
                        assert(os.path.exists(wav_file_path[:-4] + '.PHN'))
                        clip_id = speaker_dialect + '_' + speaker_id + '_' + sentence_id
                        clip_obj = {'clip_id':clip_id, 'speaker_id': speaker_id, 'sex': splits[1], 'speaker_dialect': speaker_dialect, 'is_train': is_train_set, 'is_test': is_test_set,
                                    'sentence_id': sentence_id, 'audio_path': wav_file_path, 'no_ext_path': wav_file_path[:-4]}
                        all_dataset_objects.append(clip_obj)
                        if (is_train_set): train_count += 1
                        elif (is_test_set): test_count += 1
    print("TIMIT dataset:", len(all_dataset_objects), "Train:", train_count, "Test:", test_count)

    if (part=='all'): assert(train_count+test_count==6300)
    elif (part=='train'): assert(train_count==4620)
    elif (part=='test'): assert(test_count==1680)


    '''
    if (part=='all'): assert(train_count+test_count==6300)
    elif (part=='train'): assert(train_count==4620)
    elif (part=='test'): assert(test_count==1680)
    import random
    random.seed(42)
    clips_list = sorted(clips_list, key=lambda x: random.random())
    '''

    return all_dataset_objects






def parse_timit_clip(WRD_path, PHN_path, labels):
    """
    One clip's words, each with the hand-labelled phones inside it, and the clip's boundaries.

    A phone belongs to the word whose span contains it (1 ms of tolerance at each edge). The
    silences between and around words (`h#`, `pau`) belong to no word, so they are in neither
    the words nor the boundaries; an `epi` inside a word is kept, as SIL.

    The clip's boundaries are ONSETS - where each labelled interval of a word starts - because
    onsets are what the scorer has predictions for. The end of a word's last phone is not one
    unless the next word starts there, and a silence (`epi`) starts nothing. A stop's closure
    and its release are both kept, as TIMIT labels them: evaluation/LABEL_MAPPING.md has the
    measurement behind that. A word's own `boundaries` hold the END of every interval.

    Args:
        labels: a `StdLabels` over `TIMIT_TO_STD`.
    Returns:
        `(words, boundaries)` - `boundaries` in ms from the start of the clip, sorted, unique.
    """
    sr = 16000
    words = []
    with open(WRD_path) as f:
        for line in f:
            start, end, text = line.split(' ')
            words.append({'w': text.strip(), 'sf': int(start), 's': round(int(start) / sr, 4),
                          'e': round(int(end) / sr, 4), 'r': 1.0,
                          'phones': [], 'local_ph': [], 'ph_count': [], 'gold_phg': [],
                          'boundaries': []})

    marks = set()                                  # sample positions of in-word phone onsets
    with open(PHN_path) as f:
        for line in f:
            start, end, label = line.split(' ')
            start, end, label = int(start), int(end), label.strip()
            for word in words:
                if (start / sr) + 0.001 >= word['s'] and (end / sr) - 0.001 <= word['e']:
                    local = labels.local_ph(label)
                    word['phones'].append(label)
                    word['local_ph'].extend(local)
                    word['ph_count'].append(len(local))
                    word['gold_phg'].extend(labels.gold_phg(label))
                    word['boundaries'].append(int(end * 1000 / sr))
                    if labels.is_speech(label):
                        marks.add(start)
                    break

    for word in words:
        if not word['phones']:
            print("Warning: No phonemes found for word:", word['w'])
    return words, [int(mark * 1000 / sr) for mark in sorted(marks)]


def get_audio_duration(audio_path):
    """
    Get the duration of an audio file using ffprobe
    
    Args:
        audio_path (str): Path to the audio file
    
    Returns:
        float: Duration in seconds if successful, None if failed
        str: Error message if failed, None if successful
    """
    cmd = [
        "ffprobe", "-v", "error", 
        "-show_entries", "format=duration", 
        "-of", "json", audio_path
    ]
    try:
        result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        metadata = json.loads(result.stdout)
        return float(metadata["format"]["duration"]), None
    except Exception as e:
        return None, str(e)


def assort_parts(labels, setname="train", redo_srt=False):
    '''
    Better to only use the 'train' and 'test' sets. 'val' is just a subset of 'train'.
    sets: train, test
    Total unique sentences= 2 for set train 924 clips
    {'SA2', 'SA1'}
    TIMIT dataset: 1680 Train: 0 Test: 1680
    Total unique sentences= 2 for set test 336 clips
    {'SA2', 'SA1'}
    '''
    set_names = ["train", "test", "val", "all"]
    assert(setname in set_names)

    #paths_list_name = "tmp/training/paths/paths_list_timit_"+setname+".json"
    #print("paths_list_name:", paths_list_name)
    unique_sentences = set()
    unique_speakers = set()
    unique_dialects = set()
    total_duration = 0.0
    clip_objs = load_TIMIT_db(db_path=timit_base_dir, part=setname)

    paths_list = []
    for obj in tqdm(clip_objs):
        speaker_id = obj['speaker_id']
        sentence_id = obj['sentence_id']
        #audio_id = file.split('/')[-1].replace('.flac', '')
        specific_dir = os.path.join(transcription_dir, setname, speaker_id, sentence_id)    
        if not os.path.exists(specific_dir):
            os.makedirs(specific_dir)
        PHN_path = obj['audio_path'][:-4] + '.PHN' # srt is different from the original format
        WRD_path = obj['audio_path'][:-4] + '.WRD'
        TXT_path = obj['audio_path'][:-4] + '.TXT'
        if (not os.path.exists(TXT_path)) :
            raise Exception("TXT file is missing for the audio file: " + obj['audio_path'])

        assert(os.path.exists(PHN_path))
        assert(os.path.exists(WRD_path))
        srt_path = os.path.join(specific_dir, obj['audio_path'].split('/')[-1].replace('.WAV', '.srt.json'))
        
        
        duration, error = get_audio_duration(obj['audio_path'])
        if error:
            print(f"Failed to process {obj['audio_path']}: {error}")
            continue
        
        total_duration += duration
        unique_sentences.add(obj['sentence_id'])
        unique_speakers.add(speaker_id)
        unique_dialects.add(obj['speaker_dialect'])

        
        spkr = spkr_to_id.get(speaker_id, -1)
        accent = dialect_to_id.get(obj['speaker_dialect'], -1)
        clip_obj = {'audio': obj['audio_path'].replace(timit_base_dir, '~'),
                    'srt': srt_path, 'set': setname, 
                    'WRD': WRD_path.replace(timit_base_dir, '~'),
                    'PHN': PHN_path.replace(timit_base_dir, '~'), 
                    'lang': 'en', 'duration': duration, 'spkr': spkr, 
                    'clip_id': obj['clip_id'], 'sentence_id': sentence_id, 'sex': obj['sex'], 'accent': accent}
        paths_list.append(clip_obj)


        if (redo_srt) or (not os.path.exists(srt_path)):
            # read text from TXT file
            with open(TXT_path, 'r') as txt_file:
                text_lines = txt_file.readlines()[0]
                
                # example line: 0 43418 She had your dark suit in greasy wash water all year.\n'
                text_splits = text_lines.strip().split(' ')
                # The text is everything after the first two columns (start and end frame)
                if len(text_splits) > 2:
                    text = ' '.join(text_splits[2:]).strip()
                else:
                    raise Exception("TXT file does not have enough columns: " + TXT_path + " text_splits: " + str(text_splits))
                
            words_list, boundaries = parse_timit_clip(WRD_path, PHN_path, labels)
            srt_data = {"labels": labels.header,
                        "segments": [{"start": 0.0, "end": duration, "text": text,
                                      "words": words_list, "boundaries": boundaries}],
                        "text": text}
            with open(srt_path, 'w') as f:
                json.dump(srt_data, f, ensure_ascii=False)
            #print(srt_path)
    print("Total unique sentences:", len(unique_sentences), "unique speakers:", len(unique_speakers),"for set", setname, len(paths_list), "clips")
    print("Total duration (h):", round(total_duration/3600, 2))
    assert(len(unique_dialects)==8)
    
    
    return paths_list

    

